     text.chars().take(width).collect()
 }

+fn text_lines(text: &str) -> Vec<String> {
+    let lines = text.lines().map(str::to_string).collect::<Vec<_>>();
+    if lines.is_empty() {
+        vec![String::new()]
+    } else {
+        lines
+    }
+}
+
+fn visual_selection_style() -> Style {
+    Style::default().add_modifier(Modifier::REVERSED)
+}
+
+fn line_spans_with_selection(line: &str, range: Option<(usize, usize)>) -> Spans<'static> {
+    let Some((start, end)) = range else {
+        return Spans::from(vec![Span::raw(line.to_string())]);
+    };
+    let len = line.chars().count();
+    let start = start.min(len);
+    let end = end.min(len);
+    if start >= end {
+        if line.is_empty() {
+            return Spans::from(vec![Span::styled(" ".to_string(), visual_selection_style())]);
+        }
+        return Spans::from(vec![Span::raw(line.to_string())]);
+    }
+
+    let before = slice_chars(line, 0, start);
+    let selected = slice_chars(line, start, end);
+    let after = slice_chars(line, end, len);
+    let mut spans = Vec::new();
+    if !before.is_empty() {
+        spans.push(Span::raw(before));
+    }
+    spans.push(Span::styled(selected, visual_selection_style()));
+    if !after.is_empty() {
+        spans.push(Span::raw(after));
+    }
+    Spans::from(spans)
+}
+
+fn selected_text(
+    lines: &[String],
