+    kind: VisualSelectionKind,
+) -> String {
+    let ranges = selection_ranges(lines, selection, kind);
+    lines
+        .iter()
+        .zip(ranges)
+        .filter_map(|(line, range)| {
+            range.map(|(start, end)| {
+                let len = line.chars().count();
+                slice_chars(line, start.min(len), end.min(len))
+            })
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_ranges(
+    lines: &[String],
+    selection: VisualSelection,
+    kind: VisualSelectionKind,
+) -> Vec<Option<(usize, usize)>> {
+    let mut ranges = vec![None; lines.len()];
+    if lines.is_empty() {
+        return ranges;
+    }
+
+    let anchor = clamp_text_position(selection.anchor, lines);
+    let cursor = clamp_text_position(selection.cursor, lines);
+    match kind {
+        VisualSelectionKind::Character => {
+            let (start, end) = ordered_positions(anchor, cursor);
+            for row in start.row..=end.row {
+                let line_len = lines[row].chars().count();
+                let start_column = if row == start.row { start.column } else { 0 };
+                let end_column = if row == end.row {
+                    end.column.saturating_add(1)
+                } else {
+                    line_len
+                };
+                ranges[row] = Some((start_column.min(line_len), end_column.min(line_len)));
+            }
+        }
+        VisualSelectionKind::Line => {
+            let start = anchor.row.min(cursor.row);
+            let end = anchor.row.max(cursor.row);
+            for row in start..=end {
+                ranges[row] = Some((0, lines[row].chars().count()));
+            }
+        }
+        VisualSelectionKind::Block => {
+            let top = anchor.row.min(cursor.row);
+            let bottom = anchor.row.max(cursor.row);
+            let left = anchor.column.min(cursor.column);
+            let right = anchor.column.max(cursor.column).saturating_add(1);
+            for row in top..=bottom {
+                let line_len = lines[row].chars().count();
+                ranges[row] = Some((left.min(line_len), right.min(line_len)));
+            }
+        }
+    }
+    ranges
+}
+
+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition::new(0, 0);
+    }
+    let row = position.row.min(lines.len() - 1);
+    let column = position.column.min(lines[row].chars().count());
+    TextPosition::new(row, column)
+}
+
+fn ordered_positions(
+    first: TextPosition,
+    second: TextPosition,
+) -> (TextPosition, TextPosition) {
+    if (first.row, first.column) <= (second.row, second.column) {
+        (first, second)
+    } else {
+        (second, first)
+    }
+}
+
+fn slice_chars(text: &str, start: usize, end: usize) -> String {
+    text.chars().skip(start).take(end.saturating_sub(start)).collect()
