+
+fn line_spans_with_selection(line: &str, ranges: &[(usize, usize)]) -> Spans<'static> {
+    if ranges.is_empty() {
+        return Spans::from(vec![Span::raw(line.to_string())]);
+    }
+
+    let mut spans = Vec::new();
+    let mut cursor = 0;
+    let line_width = line.chars().count();
+    for (start, end) in ranges {
+        let start = (*start).min(line_width);
+        let end = (*end).min(line_width);
+        if cursor < start {
+            spans.push(Span::raw(slice_chars(line, cursor, start)));
+        }
+        if start < end {
+            spans.push(Span::styled(
+                slice_chars(line, start, end),
+                visual_selection_style(),
+            ));
+        }
+        cursor = cursor.max(end);
+    }
+    if cursor < line_width {
+        spans.push(Span::raw(slice_chars(line, cursor, line_width)));
+    }
+    Spans::from(spans)
+}
+
+fn selected_text(
+    lines: &[String],
+    kind: VisualSelectionKind,
+    anchor: TextPosition,
+    cursor: TextPosition,
+) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+
+    let (start, end) = ordered_positions(
+        clamp_text_position(anchor, lines),
+        clamp_text_position(cursor, lines),
+    );
+    if kind == VisualSelectionKind::Line {
+        return lines[start.row..=end.row].join("\n");
+    }
+
+    let ranges = selection_ranges(lines, kind, start, end);
+    (start.row..=end.row)
+        .map(|row| {
+            ranges[row]
+                .iter()
+                .map(|(start, end)| slice_chars(&lines[row], *start, *end))
+                .collect::<String>()
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_ranges(
+    lines: &[String],
+    kind: VisualSelectionKind,
+    anchor: TextPosition,
+    cursor: TextPosition,
+) -> Vec<Vec<(usize, usize)>> {
+    let mut ranges = vec![Vec::new(); lines.len()];
+    if lines.is_empty() {
+        return ranges;
+    }
+
+    let anchor = clamp_text_position(anchor, lines);
+    let cursor = clamp_text_position(cursor, lines);
+    match kind {
+        VisualSelectionKind::Character => {
+            let (start, end) = ordered_positions(anchor, cursor);
+            for row in start.row..=end.row {
+                let line_len = lines[row].chars().count();
+                let range_start = if row == start.row { start.column } else { 0 }.min(line_len);
+                let range_end = if row == end.row {
+                    end.column.saturating_add(1)
+                } else {
+                    line_len
+                }
+                .min(line_len);
+                if range_start < range_end {
+                    ranges[row].push((range_start, range_end));
+                }
+            }
+        }
+        VisualSelectionKind::Line => {
+            let (start, end) = ordered_positions(anchor, cursor);
+            for row in start.row..=end.row {
+                ranges[row].push((0, lines[row].chars().count()));
+            }
+        }
+        VisualSelectionKind::Block => {
+            let top = anchor.row.min(cursor.row);
+            let bottom = anchor.row.max(cursor.row);
+            let left = anchor.column.min(cursor.column);
+            let right = anchor.column.max(cursor.column);
+            for row in top..=bottom {
+                let line_len = lines[row].chars().count();
+                let range_start = left.min(line_len);
+                let range_end = right.saturating_add(1).min(line_len);
+                if range_start < range_end {
+                    ranges[row].push((range_start, range_end));
+                }
+            }
+        }
+    }
+    ranges
+}
+
+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+    let row = position.row.min(lines.len() - 1);
+    let line_len = lines[row].chars().count();
+    TextPosition {
+        row,
+        column: if line_len == 0 {
+            0
+        } else {
+            position.column.min(line_len - 1)
+        },
+    }
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn slice_chars(text: &str, start: usize, end: usize) -> String {
+    text.chars().skip(start).take(end.saturating_sub(start)).collect()
+}
+
+fn move_text_position(
+    position: TextPosition,
+    lines: &[String],
+    row_delta: isize,
+    column_delta: isize,
+) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+
+    let max_row = lines.len().saturating_sub(1) as isize;
+    let row = (position.row as isize + row_delta).clamp(0, max_row) as usize;
+    let line_len = lines[row].chars().count();
+    let max_column = line_len.saturating_sub(1) as isize;
+    let column = if line_len == 0 {
+        0
+    } else {
+        (position.column as isize + column_delta).clamp(0, max_column) as usize
+    };
+    TextPosition { row, column }
+}
