+fn terminal_app_review_completion_prompts_yes_no_and_reopens_on_new_text() {
+    let root = git_repo("terminal-app-review-completion-prompt");
+    fs::write(root.join("README.md"), "before\n").unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["add", "README.md"])
+        .status()
+        .unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["commit", "-m", "ADD initial readme fixture"])
+        .status()
+        .unwrap();
+
+    let backend = FakeBackend::new([
+        "done patch\n@work-leaf patch update readme\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-before\n+after\n@work-leaf end\n@work-leaf done",
+        "summary: README changed from before to after",
+        "NO_FINDINGS",
+        "follow-up after reopen",
+    ]);
+    let chat = CommandChat::new(root, backend.clone()).with_max_review_rounds(4);
+    let mut app = TerminalApp::new(chat, 100, 24);
+
+    app.handle_bytes(b":new patch readme\n");
+    assert!(app.wait_for_idle(Duration::from_secs(2)));
+
+    let frame = app.render_frame();
+    assert!(frame.contains("work-leaf: is this feature done? yes/no"));
