+            .contains("\u{1b}[7m>patch user-1")
+    );
+
+    app.handle_bytes(b"yes\n");
+
+    assert!(app.render_frame().contains("work-leaf: feature marked done"));
+    assert!(
+        !app.ui()
+            .render_left_pane()
+            .contains("patch user-1  working: patch")
+    );
+
+    app.handle_bytes(b"one more change\n");
+    assert!(app.wait_for_idle(Duration::from_secs(1)));
+
+    let frame = app.render_frame();
